#include <iostream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex regex(R"([a-zA-Z0-9_]+)\.([a-zA-Z0-9_]+)\.([a-zA-Z0-9_]+)");
    std::regex_replace(html, regex, "<a href=\"https://example.com/$1/$2\">$1</a>");
    return html;
}

int main() {
    std::string markdown = "This is a [link](https://example.com/path/to/file)";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

